internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var userMsg = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";
        var reply = $"This is a stub response to: {userMsg}. " +
                    "The stub chat client provides deterministic outputs for NLP evaluation. " +
                    "Wire EVAL_USE_REAL_AGENT=1 with a real IChatClient for meaningful quality scores.";

        return Task.FromResult(new ChatResponse(new ChatMessage(ChatRole.Assistant, reply))
        {
            ModelId = "stub",
        });
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default) =>
        throw new NotSupportedException("Stub client does not support streaming.");

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

namespace PlainApi.Evals.Tests;

internal static class Wire
{
    public static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    public static IChatClient ResolveJudgeClient(IChatClient agentFallback)
    {
        var judgeOverride = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
        if (!string.IsNullOrEmpty(judgeOverride))
        {
            // User explicitly set a separate judge deployment — build a dedicated client.
            // For now, delegate to the agent factory (same endpoint, different deployment
            // would require custom wiring). Placeholder until the user fills in their endpoint.
            return AgentChatClientFactory.Create();
        }

        // Default: judge = agent (MEAI response cache serves both from one cache).
        return EvalEnv.UseRealJudge ? agentFallback : new StubChatClient();
    }
}

using System.Text.Json;

namespace PlainApi.Evals.Tests;

[TestClass]
public sealed class QualityTests
{
    private static ReportingConfiguration s_reporting = null!;

    [ClassInitialize]
    public static void Init(TestContext _) =>
        s_reporting = ReportingConfig.ForQuality();

    public static IEnumerable<object[]> Golden() =>
        GoldenLoader.Load().Select(g => new object[] { g.Id, g });

    [TestMethod]
    [DynamicData(nameof(Golden), DynamicDataSourceType.Method)]
    public async Task Evaluate(string scenarioId, GoldenItem g)
    {
        var scenarioName = $"{nameof(QualityTests)}.{g.Id}";
        await using var run = await s_reporting.CreateScenarioRunAsync(scenarioName);

        var agent = string.IsNullOrEmpty(
            Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME"))
                ? run.ChatConfiguration!.ChatClient
                : Wire.ResolveAgentClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, RubricLoader.SystemPrompt()),
            new(ChatRole.User, g.UserMessage),
        };
        var response = await agent.GetResponseAsync(messages);

        var contexts = new List<EvaluationContext>();
        if (!string.IsNullOrEmpty(g.ReferenceResponse))
        {
            contexts.Add(new BLEUEvaluatorContext(new[] { g.ReferenceResponse }));
            contexts.Add(new GLEUEvaluatorContext(new[] { g.ReferenceResponse }));
            contexts.Add(new F1EvaluatorContext(g.ReferenceResponse));
            contexts.Add(new EquivalenceEvaluatorContext(g.ReferenceResponse));
            contexts.Add(new CompletenessEvaluatorContext(g.ReferenceResponse));
        }
        if (!string.IsNullOrEmpty(g.Context))
            contexts.Add(new GroundednessEvaluatorContext(g.Context));

        var result = await run.EvaluateAsync(messages, response, contexts);
        Thresholds.ApplyOrLog(result, g.Id);
    }
}

public record GoldenItem(string Id, string UserMessage, string? ReferenceResponse, string? Context);

internal static class GoldenLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<GoldenItem> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");
        var doc = JsonDocument.Parse(File.ReadAllText(path));
        var scenarios = doc.RootElement.GetProperty("scenarios");
        var items = new List<GoldenItem>();
        foreach (var s in scenarios.EnumerateArray())
        {
            items.Add(new GoldenItem(
                s.GetProperty("id").GetString()!,
                s.GetProperty("user_message").GetString()!,
                s.TryGetProperty("reference_response", out var r) ? r.GetString() : null,
                s.TryGetProperty("context", out var c) ? c.GetString() : null));
        }
        return items;
    }
}

internal static class RubricLoader
{
    public static string SystemPrompt()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");
        return File.Exists(path) ? File.ReadAllText(path) : "You are a helpful assistant.";
    }
}

internal static class Thresholds
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static void ApplyOrLog(EvaluationResult result, string scenarioId)
    {
        var path = Path.Combine(AppContext.BaseDirectory, "quality.thresholds.json");
        if (!File.Exists(path)) return;

        var doc = JsonDocument.Parse(File.ReadAllText(path));
        var hardFail = doc.RootElement.TryGetProperty("hard_fail", out var hf) && hf.GetBoolean();

        if (!hardFail) return; // informational only

        if (doc.RootElement.TryGetProperty("thresholds", out var thresholds))
        {
            foreach (var metric in result)
            {
                if (thresholds.TryGetProperty(metric.Key, out var t))
                {
                    if (t.TryGetProperty("min_value", out var minVal) && metric.Value is NumericMetric nm)
                    {
                        if (nm.Value < (decimal)minVal.GetDouble())
                            Assert.Fail($"[{scenarioId}] {metric.Key} = {nm.Value} < threshold {minVal}");
                    }
                }
            }
        }
    }
}

